71	PlatformId IntelPlatformIdFromCpuId(uint32_t family, uint32_t model,
72	                                    uint32_t stepping) {
73	  if (family == 6) {
74	    // Mostly we can just map a model into a platform.
75	    // Reference: https://en.wikichip.org/wiki/intel/cpuid#Family_6
76	    static const absl::flat_hash_map<uint32_t, PlatformId> platform_id_map{
77	        {60, PlatformId::kIntelHaswell},    // Haswell Client
78	        {61, PlatformId::kIntelBroadwell},  // Broadwell Client
79	        {62, PlatformId::kIntelIvybridge},
80	        {63, PlatformId::kIntelHaswell},    // Haswell Server
81	        {69, PlatformId::kIntelHaswell},    // Haswell Client
82	        {70, PlatformId::kIntelHaswell},    // Haswell Client
83	        {71, PlatformId::kIntelBroadwell},  // Broadwell Client
84	        // Model 78 and 94 are Skylake client. Unlike the server variants, they
85	        // don't support AVX512. To support these chips, we'd need to
86	        // distinguish between Skylake client and server chips.
87	        {79, PlatformId::kIntelBroadwell},  // Broadwell
88	        {86, PlatformId::kIntelBroadwell},  // Broadwell DE
89	        {106, PlatformId::kIntelIcelake},   // Icelake Server
90	        {108, PlatformId::kIntelIcelake},   // Icelake Server
91	        {125, PlatformId::kIntelIcelake},   // Icelake Client
92	        {126, PlatformId::kIntelIcelake},   // Icelake Client
93	        // Coffeelake and Kabylake share the same CPU model but have
94	        // different stepping (Kabylake stepping <= 9) similar to
95	        // Skylake/Cascadelake. It's not clear if there's a difference between
96	        // the two cores from our standpoint.
97	        {142, PlatformId::kIntelCoffeelake},  // Also Kabylake
98	        {143, PlatformId::kIntelSapphireRapids},
99	        {151, PlatformId::kIntelAlderlake},
100	        {154, PlatformId::kIntelAlderlake},
101	        {158, PlatformId::kIntelCoffeelake},  // Also Kabylake
102	        {173, PlatformId::kIntelGraniteRapids},
103	        {207, PlatformId::kIntelEmeraldRapids},
104	    };
105	
106	    auto it = platform_id_map.find(model);
107	    if (it != platform_id_map.end()) {
108	      return it->second;
109	    }
110	
111	    // Skylake and Cascadelake Xeon.  These share the same model number.
112	    if (model == 85) {
113	      return (stepping < 5) ? PlatformId::kIntelSkylake
114	                            : PlatformId::kIntelCascadelake;
115	    }
116	  }
117	
118	  LOG_ERROR("Unknown Intel platform: family = ", family, " model = ", model,
119	            " stepping = ", stepping);
120	  return PlatformId::kUndefined;
121	}
