48	TEST(PlatformTest, PlatformArchitecture) {
49	  for (int i = proto::PlatformId_MIN; i < proto::PlatformId_MAX; ++i) {
50	    if (proto::PlatformId_IsValid(i)) {
51	      const std::string& enum_name = proto::PlatformId_Name(i);
52	      ArchitectureId arch = PlatformArchitecture(static_cast<PlatformId>(i));
53	      if (absl::StrContains(enum_name, "RESERVED") ||
54	          static_cast<PlatformId>(i) == PlatformId::kUndefined) {
